}

import { NavigationContainer } from '@react-navigation/native';
import { createNativeStackNavigator } from '@react-navigation/native-stack';
import { Button } from 'react-native';

const Stack = createNativeStackNavigator();

function Akeyi({ navigation }) {
  return <Button title="Wè detay" onPress={() => navigation.navigate('Detay')} />;
}

export default function App() {
  return (
    <NavigationContainer>
      <Stack.Navigator>
        <Stack.Screen name="Akeyi" component={Akeyi} />
      </Stack.Navigator>
    </NavigationContainer>
  );
}

import { useState, useEffect } from 'react';
import { Text, ActivityIndicator } from 'react-native';

export default function App() {
  const [done, setDone] = useState(null);

  useEffect(() => {
    (async () => {
      const r = await fetch('https://api.example.com/yo');
      setDone(await r.json());
    })();
  }, []);

  if (!done) return <ActivityIndicator />;
  return <Text>{done.non}</Text>;
}

import { useState } from 'react';
import { View, Text, TextInput, Button } from 'react-native';

export default function Fòm() {
  const [imèl, setImèl] = useState('');
  const [erè, setErè] = useState('');
  const voye = () => {
    if (!imèl.includes('@')) setErè('Imèl pa valid');
    else setErè('');
  };
  return (
    <View>
      <TextInput value={imèl} onChangeText={setImèl} placeholder="Imèl ou" keyboardType="email-address" />
      {erè ? <Text style={{ color: 'red' }}>{erè}</Text> : null}
      <Button title="Voye" onPress={voye} />
    </View>
  );
}

import { createContext, useContext, useState } from 'react';
import { Text } from 'react-native';

const TèmKontèks = createContext('klè');

function Tit() {
  const tèm = useContext(TèmKontèks);
  return <Text>Tèm: {tèm}</Text>;
}

export default function App() {
  const [tèm] = useState('fonse');
  return (
    <TèmKontèks.Provider value={tèm}>
      <Tit />
    </TèmKontèks.Provider>
  );
}

import Animated, { useSharedValue, useAnimatedStyle, withTiming } from 'react-native-reanimated';

export default function Bwat() {
  const opasite = useSharedValue(1);
  const stilAnim = useAnimatedStyle(() => ({
    opacity: opasite.value,
  }));
  const kache = () => { opasite.value = withTiming(0, { duration: 500 }); };
  return <Animated.View style={[{ width: 100, height: 100, backgroundColor: 'blue' }, stilAnim]} />;
}

